<script setup>
import {Bold,Italic,Underline,AlignLeft,AlignCenter,AlignRight} from 'lucide-vue-next';import FontSelect from './FontSelect.vue';
import {setTextDirection} from '../../shared/text-style.mjs';
defineProps({model:{type:Object,required:true}});
</script>
<template><div class="text-formatting"><label>字体<FontSelect v-model="model.fontFamily"/></label><label class="font-direction-field">文字方向<select aria-label="文字方向" :value="model.vertical?'vertical':'horizontal'" @change="setTextDirection(model,$event.target.value==='vertical')"><option value="horizontal">横向</option><option value="vertical">竖向</option></select></label><div class="text-formatting-tools" role="group" aria-label="文字样式"><button type="button" title="粗体" aria-label="粗体" :aria-pressed="model.fontWeight>=600" @click="model.fontWeight=model.fontWeight>=600?400:700"><Bold :size="15"/></button><button type="button" title="斜体" aria-label="斜体" :aria-pressed="model.fontStyle==='italic'" @click="model.fontStyle=model.fontStyle==='italic'?'normal':'italic'"><Italic :size="15"/></button><button type="button" title="下划线" aria-label="下划线" :aria-pressed="model.textDecoration==='underline'" @click="model.textDecoration=model.textDecoration==='underline'?'none':'underline'"><Underline :size="15"/></button><span/><button v-for="alignment in [{id:'left',name:'左对齐',icon:AlignLeft},{id:'center',name:'居中对齐',icon:AlignCenter},{id:'right',name:'右对齐',icon:AlignRight}]" type="button" :title="alignment.name" :aria-label="alignment.name" :aria-pressed="(model.textAlign||'center')===alignment.id" @click="model.textAlign=alignment.id"><component :is="alignment.icon" :size="15"/></button></div></div></template>
